import React, { useState } from 'react';
import FileUploader from '../components/FileUploader';
import Result from '../components/Result';
import axios from 'axios';

const JAVA_URL = 'http://localhost:8080/api';

const QuizPage = () => {
    const [result, setResult] = useState(null);
    const [error, setError] = useState(null);
    const [isLoading, setIsLoading] = useState(false);

    const handleFileUpload = async (file) => {
        if (!file) {
            setError("Veuillez sélectionner un fichier valide.");
            return;
        }

        setIsLoading(true);
        setError(null);
        setResult(null);

        try {
            // Lire le fichier comme texte
            const text = await file.text();

            // Envoyer le texte au backend
            const response = await axios.post(`${JAVA_URL}/quizzes/generate`, text, {
                headers: {
                    'Content-Type': 'text/plain'
                }
            });

            console.log('Réponse du backend:', response.data);
            setResult(response.data);
            
        } catch (error) {
            console.error('Erreur détaillée:', error);
            setError("Échec de la génération du quiz. Veuillez réessayer.");
        } finally {
            setIsLoading(false);
        }
    };

    return (
        <div className="quiz-page">
            <h1>Générer un Quiz</h1>

            <FileUploader
                onUpload={handleFileUpload}
                disabled={isLoading}
                accept=".pdf,.txt,.docx"
            />

            {isLoading && (
                <div className="loading-container">
                    <p className="loading-message">Génération du quiz en cours...</p>
                    <div className="loading-spinner"></div>
                </div>
            )}

            {error && <p className="error-message">{error}</p>}
            {result && <Result data={result} />}
        </div>
    );
};

export default QuizPage;
